import re
from decimal import Context, Decimal, Inexact, InvalidOperation

MAX_AMOUNT = Decimal("1000000.00")
_CENT = Decimal("0.01")
_AMOUNT_RE = re.compile(r"[+-]?[0-9]+(?:\.[0-9]+)?", re.ASCII)
# Private context: amounts are bounded by MAX_AMOUNT, so 50 digits is far more
# than enough for an exact quantize; Inexact is trapped so nothing is rounded.
_CTX = Context(prec=50, traps=[Inexact, InvalidOperation])


def parse_amount(value):
    if isinstance(value, Decimal):
        dec = value
    elif isinstance(value, int) and not isinstance(value, bool):
        dec = Decimal(value)  # exact for any int
    elif isinstance(value, str):
        if not _AMOUNT_RE.fullmatch(value):
            raise ValueError(f"invalid amount string: {value!r}")
        dec = Decimal(value)  # string construction is exact, context-free
    else:
        raise ValueError(f"unsupported amount type: {type(value).__name__}")

    if not dec.is_finite():
        raise ValueError("amount must be finite")
    # Decimal comparisons are exact and independent of the context precision.
    if dec <= 0:
        raise ValueError("amount must be positive")
    if dec > MAX_AMOUNT:
        raise ValueError("amount exceeds maximum")
    try:
        result = dec.quantize(_CENT, context=_CTX)
    except (Inexact, InvalidOperation):
        raise ValueError("amount is not representable in whole cents") from None
    if result != dec:
        raise ValueError("amount is not representable in whole cents")
    return result


def format_amount(value):
    return format(value, ".2f")
